.inline-block {
  display: inline-block;
  width: 120px;
  height: 80px;
  background-color: #bbdefb;
  padding: 10px;
  margin: 5px;
  border: 1px solid #90caf9;
  vertical-align: top;
}

/* Превратить span в блок */
span {
  display: block;
}

/* Превратить div в строчный */
div {
  display: inline;
}

/* Превратить span в строчно-блочный */
span {
  display: inline-block;
}
